/**
 * Contract parity vectors for the Rust port: for every request channel, valid and deliberately
 * broken inputs are generated by walking the Zod schema, and Zod's exact verdict (cleaned data, or
 * every issue with its path and message) is recorded. `crates/fin-core/tests/contract_vectors.rs`
 * replays them against the Rust validators, so both backends accept, clean and reject identically.
 * Regenerate with FIN_UPDATE_VECTORS=1 npx vitest run tests/parity.
 */
import { readFileSync, writeFileSync } from 'node:fs'
import { join } from 'node:path'
import { expect, test } from 'vitest'
import type { z } from 'zod'
import { inputSchemas } from '@shared/contract'

const FILE = join('tests', 'parity', 'vectors', 'contract.json')
const VALID_PER_CHANNEL = 12
const INVALID_PER_CHANNEL = 40

function rng(seed: number) {
  return () => {
    seed |= 0
    seed = (seed + 0x6d2b79f5) | 0
    let t = Math.imul(seed ^ (seed >>> 15), 1 | seed)
    t = (t + Math.imul(t ^ (t >>> 7), 61 | t)) ^ t
    return ((t ^ (t >>> 14)) >>> 0) / 4294967296
  }
}
const r = rng(76)
const pick = <T>(xs: readonly T[]): T => xs[Math.floor(r() * xs.length)]!
const chance = (p: number) => r() < p

type Schema = z.ZodType
type Def = {
  type: string
  shape?: Record<string, Schema>
  innerType?: Schema
  element?: Schema
  options?: Schema[]
  discriminator?: string
  entries?: Record<string, string>
  values?: unknown[]
  checks?: { _zod: { def: { check: string; minimum?: number; maximum?: number } } }[]
}
const def = (s: Schema) => (s as unknown as { _zod: { def: Def } })._zod.def
const passes = (s: Schema, v: unknown) => s.safeParse(v).success

const STRINGS = [
  'acc_01JC0000000000000000000001',
  'cat_food',
  'txn_1',
  'x',
  'Rent',
  '  Salary  ',
  'Swiggy',
  '2026-11-10',
  '2024-02-29',
  '2026-01-31',
  '2026-11',
  '2026-04',
  'INR',
  'USD',
  'Asia/Kolkata',
  'Asia/Calcutta',
  'UTC',
  'en-IN',
  'C:\\Users\\me\\backup.finbackup',
  'correct horse',
  'demo',
  'category:cat_food:2026-10',
  'UPI',
  'Weekly shop at the market',
  '',
]
const NUMBERS = [
  0, 1, 2, 5, 8, 12, 30, 60, 90, 100, 1000, 2500, 45_000, 1_25_000_00, -45_000, -1, 9_007_199_254_740_991,
]
const JUNK: unknown[] = [
  null,
  '',
  '   ',
  'x',
  'not-a-date',
  '2026-02-30',
  '2026-13-01',
  'ZZZ',
  'abc',
  'Mars/Olympus',
  '😀😀',
  0,
  -1,
  1.5,
  7,
  31,
  45,
  1e16,
  -9_007_199_254_740_992,
  9_007_199_254_740_992,
  true,
  false,
  [],
  ['x'],
  {},
  { a: 1 },
  'x'.repeat(61),
  'x'.repeat(121),
  'x'.repeat(301),
  'y'.repeat(2001),
]

function lengthBounds(d: Def): { min: number; max: number } {
  let min = 0
  let max = Infinity
  for (const c of d.checks ?? []) {
    const cd = c._zod.def
    if (cd.check === 'min_length') min = Math.max(min, cd.minimum!)
    if (cd.check === 'max_length') max = Math.min(max, cd.maximum!)
  }
  return { min, max }
}

/** A value the schema accepts (best effort; the recorded verdict is what counts). */
function valid(s: Schema, depth = 0): unknown {
  const d = def(s)
  switch (d.type) {
    case 'optional':
      return chance(0.4) ? undefined : valid(d.innerType!, depth)
    case 'nullable':
      return chance(0.2) ? null : valid(d.innerType!, depth)
    case 'object': {
      for (let attempt = 0; attempt < 30; attempt++) {
        const out: Record<string, unknown> = {}
        for (const [k, v] of Object.entries(d.shape!)) {
          const x = valid(v, depth + 1)
          if (x !== undefined) out[k] = x
        }
        if (passes(s, out)) return out
      }
      return {}
    }
    case 'string': {
      const ok = STRINGS.filter((x) => passes(s, x))
      if (ok.length) return pick(ok)
      const { min, max } = lengthBounds(d)
      const n = Math.min(Math.max(min, 1), max)
      return 'a'.repeat(n)
    }
    case 'number': {
      const ok = NUMBERS.filter((x) => passes(s, x))
      return ok.length ? pick(ok) : 0
    }
    case 'boolean':
      return chance(0.5)
    case 'enum':
      return pick(Object.values(d.entries!))
    case 'literal':
      return pick(d.values!)
    case 'union':
      return valid(pick(d.options!), depth)
    case 'array': {
      const { min, max } = lengthBounds(d)
      const n = Math.min(max, min + Math.floor(r() * 3))
      return Array.from({ length: n }, () => valid(d.element!, depth + 1))
    }
    default:
      return undefined
  }
}

/** Break one spot in a valid value: wrong type, out of range, missing key, extra key... */
function mutate(v: unknown): unknown {
  if (chance(0.08)) return pick([null, 'str', 5, [], undefined, true])
  if (v && typeof v === 'object' && !Array.isArray(v)) {
    const o = { ...(v as Record<string, unknown>) }
    const keys = Object.keys(o)
    const roll = r()
    if (roll < 0.15 || keys.length === 0) {
      o[pick(['extra', 'id', 'name', 'amountMinor', 'postedDate', 'unknownKey'])] = pick(JUNK)
      return o
    }
    const k = pick(keys)
    if (roll < 0.3) delete o[k]
    else o[k] = chance(0.6) ? mutate(o[k]) : pick(JUNK)
    return o
  }
  if (Array.isArray(v)) {
    if (v.length === 0 || chance(0.3)) return [...v, pick(JUNK)]
    const i = Math.floor(r() * v.length)
    const copy = [...v]
    copy[i] = mutate(copy[i])
    return copy
  }
  return pick(JUNK)
}

type Case = { channel: string; input?: unknown; ok: boolean; data?: unknown; issues?: [string, string][] }

function verdict(channel: string, schema: Schema, raw: unknown): Case {
  // What actually arrives over the bridge: JSON (undefined inside arrays becomes null).
  const input: unknown = raw === undefined ? undefined : JSON.parse(JSON.stringify(raw))
  const res = schema.safeParse(input)
  const c: Case = { channel, ok: res.success }
  if (input !== undefined) c.input = input
  if (res.success) {
    if (res.data !== undefined) c.data = res.data
  } else {
    c.issues = res.error.issues.map((i) => [i.path.join('.'), i.message])
  }
  return c
}

function build(): Case[] {
  const cases: Case[] = []
  for (const [channel, schema] of Object.entries(inputSchemas) as [string, Schema][]) {
    const seen = new Set<string>()
    const add = (input: unknown) => {
      const key = JSON.stringify(input) ?? 'undefined'
      if (seen.has(key)) return
      seen.add(key)
      cases.push(verdict(channel, schema, input))
    }
    const valids: unknown[] = []
    for (let i = 0; i < VALID_PER_CHANNEL; i++) {
      const v = valid(schema)
      valids.push(v)
      add(v)
    }
    for (let i = 0; i < INVALID_PER_CHANNEL; i++) add(mutate(pick(valids)))
  }
  return cases
}

test('contract parity vectors are up to date', () => {
  const cases = build()
  // Enough of both kinds for every channel, or the vectors prove little.
  const channels = new Set(cases.map((c) => c.channel))
  for (const channel of channels) {
    expect(
      cases.some((c) => c.channel === channel && c.ok),
      `${channel} has a valid case`,
    ).toBe(true)
  }
  const json = `${JSON.stringify(cases, null, 0).replaceAll('},{"channel"', '},\n{"channel"')}\n`
  if (process.env.FIN_UPDATE_VECTORS) writeFileSync(FILE, json)
  expect(readFileSync(FILE, 'utf8')).toBe(json)
})
